WITH with_windows AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY segment ORDER BY age DESC, id) AS event_seq, PERCENT_RANK() OVER (PARTITION BY city ORDER BY age DESC NULLS FIRST) AS age_percent_rank, LEAD(credit_limit, 2, 0) OVER (ORDER BY signup_date, id) AS next_credit_limit, ROUND(credit_limit / SUM(credit_limit) OVER (PARTITION BY city, segment), 4) AS credit_limit_share, ROW_NUMBER() OVER (ORDER BY signup_date DESC, id) AS event_seq_2 FROM customers) SELECT city, COUNT(DISTINCT country) AS distinct_countries, COUNT(*) AS num_rows, COUNT_IF(segment = 'SMB') AS smb_events, COUNT(CASE WHEN country = 'TH' THEN 1 END) AS th_count FROM with_windows GROUP BY city ORDER BY city DESC NULLS LAST
